'use client'
import certificates1 from '../asset/certificates-1.png';
import gallery1 from '../asset/gallery1.jpeg';
import gallery2 from '../asset/gallery2.jpeg';
import gallery3 from '../asset/gallery3.webp';

export default function Gallery() {

  return (
    <div className="bg-white block mt-24 overflow-hidden">
      <div className="flex">
        <img src={gallery3} className="md:w-full md:h-[48rem] object-cover" />
      </div>
      <div className="md:flex">
        <img src={gallery1} className="md:w-[70%] md:h-[50rem] object-cover" />
        <img src={gallery2} className="md:w-[30%] md:h-[50rem] object-cover" />
      </div>
    </div>
  );
}

